package com.ecobridge.repository; import com.ecobridge.entity.EcoEventEntity; import jakarta.persistence.LockModeType; import org.springframework.data.jpa.repository.*; import org.springframework.data.repository.query.Param; import java.util.*; public interface EventRepository extends JpaRepository<EcoEventEntity,Long>{List<EcoEventEntity> findAllByOrderByDateAsc(); @Lock(LockModeType.PESSIMISTIC_WRITE) @Query("select e from EcoEventEntity e where e.id=:id") Optional<EcoEventEntity> findByIdForUpdate(@Param("id") Long id);}
